refentry.refsect1:
  &reftitle.examples;



    metaphone को आधारभूत उदाहरण


<?php
var_dump(metaphone('programming'));
var_dump(metaphone('programmer'));
?>


    &example.outputs;


string(7) "PRKRMNK"
string(6) "PRKRMR"







    max_phonemes parameter को प्रयोग


<?php
var_dump(metaphone('programming', 5));
var_dump(metaphone('programmer', 5));
?>


    &example.outputs;


string(5) "PRKRM"
string(5) "PRKRM"







    max_phonemes parameter को प्रयोग
    यस उदाहरणमा, metaphone लाई पाँच वर्णको एउटा string बनाउन भनिएको छ, तर त्यसका लागि final phoneme लाई टुक्र्याउनुपर्ने हुन्छ ('x' लाई 'KS' मा transcribe गरिनुपर्ने हो), त्यसैले function ले छवटा वर्ण भएको एउटा string return गर्दछ।


<?php
var_dump(metaphone('Asterix', 5));
?>


    &example.outputs;


string(6) "ASTRKS"
